def update_one(notion_url: str, content: str) -> int:
    # PostgREST: 비ASCII URL 인코딩 필요
    encoded = urllib.parse.quote(notion_url, safe="")
    url = f"{SUPABASE_URL}/rest/v1/mj_interview_records?notion_url=eq.{encoded}"
    payload = json.dumps({"content": content}, ensure_ascii=False).encode("utf-8")
    headers = {
        "apikey": SUPABASE_KEY,
        "Authorization": f"Bearer {SUPABASE_KEY}",
        "Content-Type": "application/json",
        "Prefer": "return=minimal",
    }
    req = urllib.request.Request(url, data=payload, headers=headers, method="PATCH")
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            return resp.status
    except urllib.error.HTTPError as e:
        body = e.read().decode("utf-8", errors="replace")[:200]
        print(f"FAIL {notion_url[-12:]}: HTTP {e.code} {body}")
        return e.code


def main() -> None:
    ok = 0
    for url, content in INTERVIEWS:
        status = update_one(url, content)
        if status in (200, 204):
            ok += 1
    print(f"Updated {ok}/{len(INTERVIEWS)}")


if __name__ == "__main__":
    main()
